-- legacy master.CarSeries (ตรงกับ car_variants ของเรา) มีข้อมูลสเปครถเพิ่มเติมมาก
-- เกินกว่า simple lookup pattern ธรรมดา — เพิ่ม column ให้ครบตามของจริง
ALTER TABLE car_variants ADD COLUMN cm_code            VARCHAR(50);
ALTER TABLE car_variants ADD COLUMN cm_code_new        VARCHAR(50);
ALTER TABLE car_variants ADD COLUMN car_type           VARCHAR(10);
ALTER TABLE car_variants ADD COLUMN car_year_made_new  INT;
ALTER TABLE car_variants ADD COLUMN car_year_made      INT;
ALTER TABLE car_variants ADD COLUMN chassis_code       VARCHAR(50);
ALTER TABLE car_variants ADD COLUMN seat                INT;
ALTER TABLE car_variants ADD COLUMN cc                  INT;
ALTER TABLE car_variants ADD COLUMN weight              INT;
ALTER TABLE car_variants ADD COLUMN door                INT;

-- legacy master.CarSeries มีบางแถวไม่ใส่ชื่อไว้เหมือนกับ master.Title — รองรับ NULL ได้
ALTER TABLE car_variants ALTER COLUMN name_th DROP NOT NULL;
-- และมี 1 แถวที่ car_model_id เป็น NULL จริงในต้นฉบับ (ไม่ผูกกับรุ่นรถใดเลย) — รองรับ NULL ได้เช่นกัน
ALTER TABLE car_variants ALTER COLUMN car_model_id DROP NOT NULL;

COMMENT ON TABLE car_variants IS 'ข้อมูลอ้างอิงรุ่นย่อยรถ (จาก legacy master.CarSeries) — code = car_series_code เดิม (ใช้แทน id เพราะไม่มีตารางอื่นอ้างอิง car_series_id โดยตรง ต่างจาก car_makes/car_models)';

